  fig,ax=plt.subplots(figsize=(8.6,4.7),layout='constrained');ax.plot(e,[float(r['validation_macro_f1']) for r in rows],color=COLORS[k]);ax.scatter([best],[float(by[k]['macro_f1'])],marker='*',s=120,color=COLORS[k],edgecolor='black',label=f'Selected epoch {best}');ax.set(xlabel=xlabel,ylabel='Validation macro-F1',title=name+'\nValidation macro-F1 by epoch');ax.set_ylim(0,1);ax.legend(frameon=False);save_figure(c,'03_Training_Curves',f'{k}_validation_macro_f1',fig,name+' — validation macro-F1','Recorded validation macro-F1 with the selected checkpoint marked. Early stopping uses patience six; no heldout test or PAD score enters selection.',[data/'epoch_histories.csv',data/'model_metrics.csv'],models=[k])
  lr=[r for r in lrs if r['model']==k];fig,ax=plt.subplots(figsize=(8.6,4.7),layout='constrained');ax.step(e,[float(r['head_lr']) for r in lr],where='mid',color=COLORS[k],label='Classification head');ax.step(e,[float(r['backbone_lr']) for r in lr],where='mid',color=COLORS[k],ls='--',label='Backbone (0 = frozen/no group)');ax.set_yscale('symlog',linthresh=1e-7);ax.axvline(best,color='#333333',ls=':');ax.set(xlabel=xlabel,ylabel='Optimizer learning rate (symlog)',title=name+'\nExact recorded learning rates');ax.legend(frameon=False);save_figure(c,'03_Training_Curves',f'{k}_learning_rates',fig,name+' — optimizer learning rates','Reconstructed from each saved epoch optimizer state, not guessed from a configuration. Backbone zero means no optimizer group while frozen, not an observed zero-valued backbone optimizer LR. The dotted line marks the selected checkpoint.',[data/'exact_learning_rates.csv',data/'model_metrics.csv'],models=[k],method='actual optimizer-state history')
