def dataset(c):
 data=c['data'];eligible=[r for r in c['manifest'] if r['release_eligible']=='True'];rows=[]
 for split in ['train','validation','test','external']:
  for cl in CLASSES:rows.append({'split':split,'class':cl,'images':sum(r['split']==split and r['label']==cl for r in eligible),'image_access':'metadata only; no image evaluation' if split in ['test','external'] else 'permitted research split'})
 path=write_csv(data/'approved_dataset_counts.csv',rows);train=np.array([next(r['images'] for r in rows if r['split']=='train' and r['class']==cl) for cl in CLASSES]);imb=[{'class':cl,'training_images':int(n),'majority_to_class_ratio':float(train.max()/n),'fraction_of_train':float(n/train.sum())} for cl,n in zip(CLASSES,train)];ip=write_csv(data/'class_imbalance.csv',imb)
 fig,ax=plt.subplots(figsize=(8.5,4.8),layout='constrained');bars=ax.bar(CLASSES,train,color=CLASS_COLORS);ax.bar_label(bars,padding=3);ax.set_ylim(0,train.max()*1.14);ax.set(ylabel='Retained training images',title='Approved four-class training distribution');save_figure(c,'01_Dataset_Analysis','training_distribution',fig,'Approved four-class training distribution','Counts from approved immutable release only:6838NV,2611MEL,1799BCC,384SCC. Original image assignments and exclusions are unchanged.',[path],split='train')
 totals=[sum(r['images'] for r in rows if r['split']==sp) for sp in ['train','validation','test','external']];fig,ax=plt.subplots(figsize=(10,4.8),layout='constrained');bars=ax.bar(['ISIC training','ISIC validation','ISIC internal test\n(metadata only)','PAD external\n(metadata only)'],totals,color=['#4E79A7','#76B7B2','#BBBBBB','#DDDDDD']);ax.bar_label(bars,padding=3);ax.set_ylim(0,max(totals)*1.15);ax.set(ylabel='Eligible images',title='Approved split sizes — metadata counts only');fig.supxlabel('Locked ISIC test and PAD images were not evaluated',fontsize=9);save_figure(c,'01_Dataset_Analysis','split_counts_metadata',fig,'Approved train/validation/test/PAD counts','Only approved metadata is counted for locked ISIC test2703 and PAD1303. Neither heldout partition is opened for predictions, XAI, calibration or selection in this package.',[path],split='approved metadata only; test/PAD not evaluated')
 fig,ax=plt.subplots(figsize=(8.5,4.8),layout='constrained');vals=[r['majority_to_class_ratio'] for r in imb];bars=ax.bar(CLASSES,vals,color=CLASS_COLORS);ax.bar_label(bars,fmt='%.2f×',padding=3);ax.set_ylim(0,max(vals)*1.17);ax.set(ylabel='Largest training class / class count',title='Training class imbalance ratios');save_figure(c,'01_Dataset_Analysis','imbalance_ratios',fig,'Approved training imbalance ratios','Ratios use retained training counts only. They are descriptive data properties, not new loss weights or evidence of clinical prevalence.',[ip],split='train')
 rng=np.random.default_rng(42);chosen=[];assets=data/'sample_assets';assets.mkdir(exist_ok=True)
 for cl in CLASSES:
  pool=sorted([r for r in eligible if r['split']=='train' and r['label']==cl],key=lambda r:r['image']);ix=rng.choice(len(pool),size=2,replace=False)
  for j,index in enumerate(ix):
   r=pool[int(index)];prepared=ROOT/r['processed_path'];assert sha(prepared)==r['processed_sha256'];pc=assets/f"{r['image']}_prepared.jpg"
   if not pc.exists():shutil.copyfile(prepared,pc)
   rawcopy=''
   if j==0:
    raw=Path(r['source']);assert sha(raw)==r['source_sha256'];rawpath=assets/f"{r['image']}_raw{raw.suffix.lower()}"
    if not rawpath.exists():shutil.copyfile(raw,rawpath)
    rawcopy=str(rawpath.relative_to(c['out']))
   chosen.append({'image':r['image'],'label':cl,'split':'train','selection':'seed42 two randomly chosen images per class; illustrative, not statistically representative','processed_original_path':r['processed_path'],'processed_package_asset':str(pc.relative_to(c['out'])),'processed_sha256':r['processed_sha256'],'raw_package_asset':rawcopy,'raw_sha256':r['source_sha256'] if j==0 else ''})
 sample=write_csv(data/'sample_selection.csv',chosen)
 fig,axes=plt.subplots(2,4,figsize=(10.8,6),layout='constrained')
 for i,cl in enumerate(CLASSES):
  for j,r in enumerate([x for x in chosen if x['label']==cl]):
   with Image.open(c['out']/r['processed_package_asset']) as im:axes[j,i].imshow(im.copy())
   axes[j,i].axis('off');axes[j,i].set_title(cl+'\n'+r['image'],fontsize=8)
 save_figure(c,'01_Dataset_Analysis','training_sample_grid',fig,'Illustrative approved training examples','Two seed-42 images per true class from eligible training only. Labels come from the approved release; these few examples are illustrative, not a representativeness or clinical-diagnostic claim. Images:ISIC2019/BCN20000,HAM10000,MSK under CC BY-NC4.0; attribution is supplied in the package.',[sample]+[c['out']/r['processed_package_asset'] for r in chosen],split='train')
